package com.example.demo.config;

import java.io.IOException;

import jakarta.servlet.Filter;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.ServletRequest;
import jakarta.servlet.ServletResponse;
import jakarta.servlet.http.HttpServletRequest;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Minimal pass-through request logging filter (jakarta.servlet based).
 *
 * Registered by {@link WebConfig#loggingFilter()} for {@code /api/*}. It only
 * logs the incoming request and delegates unchanged, so it carries no business
 * logic. (Added on the Boot 3.x migration: the original registration never set
 * a filter, which aborted startup in Tomcat with "Filter must not be null".)
 */
public class LoggingFilter implements Filter {

    private static final Logger log = LoggerFactory.getLogger(LoggingFilter.class);

    @Override
    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        if (request instanceof HttpServletRequest httpRequest) {
            log.info("{} {}", httpRequest.getMethod(), httpRequest.getRequestURI());
        }
        chain.doFilter(request, response);
    }
}

